import {zoneGrowthReport,GROWTH_REASONS} from './zone-growth.js?v=shaped-details-1';
const states={all:'All development',abandoned:'Abandoned buildings',blocked:'Service or site problems',demand:'Waiting for demand',capped:'At a density limit',maturing:'Still maturing',ready:'Growth eligible'};
export function showZoneGrowth(ui){const rows=zoneGrowthReport(ui.city()),$=s=>document.querySelector(s);let page=0,visible=[];
 ui.dialog('Zone development · find stalled growth',`<p>Zoning sets a maximum; development also needs local demand, usable services and suitable land value. This report uses the same conditions as the monthly growth check.</p><p>${rows.length.toLocaleString()} building lots or unbuilt zone tiles. Multi-tile buildings count once; farms follow separate formation and expansion rules in Industry & farming.</p><div class="actions"><label>Sector<select id="growthSector"><option value="all">All sectors</option><option value="residential">Residential</option><option value="commercial">Commercial</option><option value="industrial">Industrial</option></select></label><label>Development state<select id="growthState">${Object.entries(states).map(([key,label])=>`<option value="${key}">${label}${key==='all'?'':' · '+rows.filter(row=>key==='abandoned'?row.abandoned:row.state===key).length}</option>`).join('')}</select></label></div><div id="growthResults" aria-live="polite"></div><div class="actions"><button id="growthPrevious">Previous 50</button><button id="growthNext">Next 50</button><button id="growthBack">Back to city desk</button></div><p class="fine">These are current conditions. Monthly utility, demographic and economic updates can change them before growth is checked. Eligible sites still wait for probabilistic development; this is not a promise of growth next month. A site can have several constraints. Established buildings lose a level after four consecutive unusable checks; very low demand can also cause abandonment. Low-density zones can begin without water, while larger development needs it.</p>`);
 function render(){const sector=$('#growthSector').value,state=$('#growthState').value,filtered=rows.filter(row=>(sector==='all'||row.type===sector)&&(state==='all'||(state==='abandoned'?row.abandoned:row.state===state)));page=Math.min(page,Math.max(0,Math.ceil(filtered.length/50)-1));visible=filtered.slice(page*50,page*50+50);$('#growthResults').innerHTML=`<p>${filtered.length?`${page*50+1}–${page*50+visible.length} of ${filtered.length}`:'No matching zones.'}</p>${visible.length?`<div class="table-scroll"><table><thead><tr><th scope="col">Location · sector</th><th scope="col">Development</th><th scope="col">Local demand</th><th scope="col">Conditions</th><th scope="col">Locate</th></tr></thead><tbody>${visible.map((row,index)=>`<tr><th scope="row">${row.x+1}, ${row.y+1} · ${row.type}<br><small>${row.tiles} ${row.tiles===1?'tile':'tiles'}</small></th><td>${row.abandoned?'<strong>Abandoned</strong><br>':''}Level ${row.level} / ${row.limit} currently allowed<br><small>Zoned maximum ${row.density}</small></td><td>${Math.round(row.demand)}</td><td>${row.reasons.map(key=>GROWTH_REASONS[key]).join('; ')}</td><td><button data-growth-map="${index}" aria-label="Show zone at ${row.x+1}, ${row.y+1}">Show on map</button><button data-growth-inspect="${index}" aria-label="Inspect zone at ${row.x+1}, ${row.y+1}">Inspect</button></td></tr>`).join('')}</tbody></table></div>`:''}`;$('#growthPrevious').disabled=page===0;$('#growthNext').disabled=(page+1)*50>=filtered.length;for(const action of ['map','inspect'])document.querySelectorAll('[data-growth-'+action+']').forEach(button=>button.onclick=()=>{const row=visible[Number(button.dataset[action==='map'?'growthMap':'growthInspect'])];ui.locate({x:row.x,y:row.y},action==='inspect');});}
 $('#growthSector').onchange=$('#growthState').onchange=()=>{page=0;render();};$('#growthPrevious').onclick=()=>{page=Math.max(0,page-1);render();};$('#growthNext').onclick=()=>{page++;render();};$('#growthBack').onclick=ui.back;render();
}
